// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;
    bool reverted;

    function setUp() public {
        vm.deal(address(this), 1000000000000000000000000000000);
        c = new SimpleWallet();
    }

    function _run(uint _value) internal {
        vm.deal(address(c), 1000000000000000000000000);
        vm.assume(true);
        vm.deal(address(this), 1000000000000000000000000000000);
        vm.assume(address(this).balance >= _value);
        uint before = address(this).balance;
        bool reverted;
        try c.sendMoney(address(this), _value, "") { reverted = false; } catch { reverted = true; }
        assertTrue(reverted || address(this).balance == before + _value);
    }

    function testFuzz_run(uint _value) public {
        _run(_value);
    }

    receive() external payable {}
}
